import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  FaComments, FaClock, FaHeartbeat, FaBrain, FaFire, FaCalendar, 
  FaUser, FaBook, FaUserSecret, FaChartLine, FaExclamationTriangle,
  FaCheckCircle, FaCircle, FaPlus, FaTrash
} from 'react-icons/fa';
import Navbar from '../components/Navbar';
import MoodTracker from '../components/MoodTracker';
import StatsCard from '../components/StatsCard';

function Dashboard() {
  const navigate = useNavigate();
  const [userName, setUserName] = useState('');
  const [userAvatar, setUserAvatar] = useState(null);
  const [greeting, setGreeting] = useState('');
  const [selectedMood, setSelectedMood] = useState(null);
  
  // Academic Load State
  const [academicItems, setAcademicItems] = useState([]);
  const [showAcademicForm, setShowAcademicForm] = useState(false);
  const [newAcademicItem, setNewAcademicItem] = useState({
    title: '',
    type: 'exam',
    dueDate: '',
    priority: 'medium'
  });

  // Burnout Tip State
  const [currentTip, setCurrentTip] = useState('');
  
  // Anonymous Message State
  const [anonymousMessage, setAnonymousMessage] = useState('');
  const [anonymousResponse, setAnonymousResponse] = useState('');

  const burnoutTips = [
    "Take a 5-minute break between study sessions 🧘",
    "Get at least 7-8 hours of sleep tonight 😴",
    "Drink water and stay hydrated 💧",
    "Talk to a friend or family member 💬",
    "Practice deep breathing for 2 minutes 🌬️",
    "Step outside for fresh air 🌞",
    "Listen to calming music 🎵",
    "Write down 3 things you're grateful for 📝"
  ];

  const stats = {
    streak: 12,
    totalFocus: 245,
    habitsCompleted: 18,
    badges: 8
  };

  useEffect(() => {
    const name = localStorage.getItem('userName') || 'Friend';
    const avatar = localStorage.getItem('userAvatar');
    setUserName(name);
    setUserAvatar(avatar);
    
    const hour = new Date().getHours();
    if (hour < 12) setGreeting('🌅 Good Morning');
    else if (hour < 18) setGreeting('☀️ Good Afternoon');
    else setGreeting('🌙 Good Evening');
    
    // Load academic items
    const savedAcademic = localStorage.getItem('academicLoad');
    if (savedAcademic) setAcademicItems(JSON.parse(savedAcademic));
    
    // Set random burnout tip
    setCurrentTip(burnoutTips[Math.floor(Math.random() * burnoutTips.length)]);
  }, []);

  // Save academic items to localStorage
  const saveAcademicItems = (items) => {
    setAcademicItems(items);
    localStorage.setItem('academicLoad', JSON.stringify(items));
  };

  // Add academic item
  const addAcademicItem = () => {
    if (newAcademicItem.title && newAcademicItem.dueDate) {
      const newItems = [...academicItems, { ...newAcademicItem, id: Date.now(), completed: false }];
      saveAcademicItems(newItems);
      setNewAcademicItem({ title: '', type: 'exam', dueDate: '', priority: 'medium' });
      setShowAcademicForm(false);
    }
  };

  // Toggle academic item completion
  const toggleAcademicComplete = (id) => {
    const newItems = academicItems.map(item => 
      item.id === id ? { ...item, completed: !item.completed } : item
    );
    saveAcademicItems(newItems);
  };

  // Delete academic item
  const deleteAcademicItem = (id) => {
    const newItems = academicItems.filter(item => item.id !== id);
    saveAcademicItems(newItems);
  };

  // Handle anonymous message
  const handleAnonymousMessage = () => {
    if (anonymousMessage.trim()) {
      const responses = [
        "Thank you for sharing. You're not alone. 💙",
        "I hear you. Your feelings are valid. 🌸",
        "That sounds challenging. Would you like to talk more? 💬",
        "Remember to be kind to yourself. You're doing great! ✨",
        "Take a deep breath. One step at a time. 🧘",
        "Would you like to try a quick breathing exercise? 🌬️"
      ];
      setAnonymousResponse(responses[Math.floor(Math.random() * responses.length)]);
      setTimeout(() => setAnonymousResponse(''), 5000);
      setAnonymousMessage('');
    }
  };

  const getTypeIcon = (type) => {
    switch(type) {
      case 'exam': return '📝';
      case 'assignment': return '📄';
      case 'club': return '👥';
      case 'work': return '💼';
      default: return '📌';
    }
  };

  const getPriorityColor = (priority) => {
    if (priority === 'high') return '#e74c3c';
    if (priority === 'medium') return '#f39c12';
    return '#2ecc71';
  };

  const upcomingItems = academicItems.filter(i => !i.completed).slice(0, 3);

  const quickActions = [
    { icon: <FaComments size={20} />, label: 'AI Chat', color: '#667eea', path: '/chat', desc: 'Talk to AI' },
    { icon: <FaClock size={20} />, label: 'Focus Timer', color: '#e74c3c', path: '/timer', desc: 'Boost focus' },
    { icon: <FaHeartbeat size={20} />, label: 'Mood Check', color: '#2ecc71', path: '/habits', desc: 'Track mood' },
    { icon: <FaBrain size={20} />, label: 'Insights', color: '#f39c12', path: '/profile', desc: 'View stats' },
  ];

  const inspirationalQuotes = [
    { quote: "You are stronger than you think", author: "MindEase" },
    { quote: "One small step at a time", author: "MindEase" },
    { quote: "Your mental health matters", author: "You" },
    { quote: "Breathe. It's just a bad day, not a bad life", author: "Anonymous" },
  ];

  const randomQuote = inspirationalQuotes[Math.floor(Math.random() * inspirationalQuotes.length)];

  return (
    <div style={styles.container}>
      <Navbar />
      
      <div style={styles.content}>
        {/* Welcome Card */}
        <div style={styles.welcomeCard}>
          <div style={styles.welcomeContent}>
            <div style={styles.userInfoContainer}>
              <div style={styles.avatarContainer}>
                {userAvatar ? (
                  <img src={userAvatar} alt="Avatar" style={styles.userAvatar} />
                ) : (
                  <div style={styles.avatarPlaceholder}>
                    <FaUser size={20} color="#fff" />
                  </div>
                )}
              </div>
              <div>
                <h2 style={styles.greeting}>{greeting}, {userName}! 👋</h2>
                <p style={styles.welcomeText}>Ready to nurture your wellness today?</p>
              </div>
            </div>
            <div style={styles.streakBadge}>
              <FaFire color="#e74c3c" size={18} />
              <span style={styles.streakNumber}>{stats.streak}</span>
              <span style={styles.streakText}>day streak</span>
            </div>
          </div>
          
          <div style={styles.quoteBox}>
            <p style={styles.quoteText}>✨ "{randomQuote.quote}"</p>
            <p style={styles.quoteAuthor}>— {randomQuote.author}</p>
          </div>
        </div>

        {/* Stats Row */}
        <div style={styles.statsRow}>
          <div style={styles.statTile}>
            <div style={styles.statIconSmall}><FaFire color="#e74c3c" size={16} /></div>
            <div style={styles.statValueSmall}>{stats.streak}</div>
            <div style={styles.statLabelSmall}>Day Streak</div>
          </div>
          <div style={styles.statTile}>
            <div style={styles.statIconSmall}><FaClock color="#3498db" size={16} /></div>
            <div style={styles.statValueSmall}>{stats.totalFocus}</div>
            <div style={styles.statLabelSmall}>Focus Minutes</div>
          </div>
          <div style={styles.statTile}>
            <div style={styles.statIconSmall}><FaCalendar color="#2ecc71" size={16} /></div>
            <div style={styles.statValueSmall}>{stats.habitsCompleted}</div>
            <div style={styles.statLabelSmall}>Habits Done</div>
          </div>
          <div style={styles.statTile}>
            <div style={styles.statIconSmall}><FaBrain color="#9b59b6" size={16} /></div>
            <div style={styles.statValueSmall}>{stats.badges}</div>
            <div style={styles.statLabelSmall}>Badges</div>
          </div>
        </div>

        {/* Three New Cards Row */}
        <div style={styles.threeCardsRow}>
          
          {/* Academic Load Card */}
          <div style={styles.featureCard}>
            <div style={styles.cardHeader}>
              <h3><FaBook /> Academic Load</h3>
              <button onClick={() => setShowAcademicForm(true)} style={styles.smallAddBtn}>+ Add</button>
            </div>
            {upcomingItems.length === 0 ? (
              <p style={styles.cardEmpty}>No pending tasks. Add exams or assignments!</p>
            ) : (
              upcomingItems.map(item => (
                <div key={item.id} style={{...styles.academicItem, borderLeftColor: getPriorityColor(item.priority)}}>
                  <div style={styles.academicItemLeft}>
                    <span style={styles.academicItemIcon}>{getTypeIcon(item.type)}</span>
                    <div>
                      <p style={styles.academicItemTitle}>{item.title}</p>
                      <p style={styles.academicItemDate}>📅 {new Date(item.dueDate).toLocaleDateString()}</p>
                    </div>
                  </div>
                  <div style={styles.academicItemActions}>
                    <div onClick={() => toggleAcademicComplete(item.id)} style={styles.smallCheck}>
                      {item.completed ? <FaCheckCircle color="#2ecc71" size={16} /> : <FaCircle color="#ccc" size={16} />}
                    </div>
                    <button onClick={() => deleteAcademicItem(item.id)} style={styles.smallDeleteBtn}>
                      <FaTrash size={12} />
                    </button>
                  </div>
                </div>
              ))
            )}
            {academicItems.length > 3 && (
              <button onClick={() => navigate('/academic-load')} style={styles.viewMoreBtn}>
                View All ({academicItems.length}) →
              </button>
            )}
          </div>

          {/* Burnout Check Card */}
          <div style={styles.featureCard}>
            <div style={styles.cardHeader}>
              <h3><FaExclamationTriangle /> Burnout Check</h3>
              <button onClick={() => navigate('/burnout')} style={styles.smallAssessBtn}>Assess</button>
            </div>
            <div style={styles.burnoutTip}>
              <FaBrain color="#667eea" size={18} />
              <p>{currentTip}</p>
            </div>
            <div style={styles.burnoutWarning}>
              <FaChartLine size={14} color="#f39c12" />
              <span>Early recognition prevents burnout</span>
            </div>
            <button onClick={() => navigate('/burnout')} style={styles.fullWidthBtn}>
              Take Burnout Assessment →
            </button>
          </div>

          {/* Anonymous Chat Card */}
          <div style={styles.featureCard}>
            <div style={styles.cardHeader}>
              <h3><FaUserSecret /> Anonymous Support</h3>
              <span style={styles.anonymousBadge}>🔒 100% Anonymous</span>
            </div>
            <div style={styles.anonymousChatArea}>
              <textarea
                placeholder="Share what's on your mind... (completely anonymous)"
                value={anonymousMessage}
                onChange={(e) => setAnonymousMessage(e.target.value)}
                style={styles.anonymousInput}
                rows="3"
              />
              {anonymousResponse && (
                <div style={styles.anonymousResponse}>
                  <FaHeartbeat color="#e84393" size={14} />
                  <p>{anonymousResponse}</p>
                </div>
              )}
              <button onClick={handleAnonymousMessage} style={styles.sendAnonymousBtn}>
                Send Anonymous Message 💬
              </button>
            </div>
          </div>
        </div>

        {/* Mood Tracker Section */}
        <div style={styles.section}>
          <div style={styles.sectionHeader}>
            <h3>🎭 How are you feeling right now?</h3>
          </div>
          <MoodTracker selectedMood={selectedMood} setSelectedMood={setSelectedMood} />
        </div>

        {/* Quick Actions Section */}
        <div style={styles.section}>
          <div style={styles.sectionHeader}>
            <h3>⚡ Quick Actions</h3>
          </div>
          <div style={styles.actionGrid}>
            {quickActions.map((action, index) => (
              <div
                key={index}
                style={{...styles.actionCard, borderTop: `4px solid ${action.color}`}}
                onClick={() => navigate(action.path)}
              >
                <div style={{...styles.actionIconSmall, background: `${action.color}20`, color: action.color}}>
                  {action.icon}
                </div>
                <h4 style={styles.actionLabelSmall}>{action.label}</h4>
                <p style={styles.actionDescSmall}>{action.desc}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Emergency Banner */}
        <div style={styles.emergencyBanner}>
          <div>
            <h4>🚨 Need immediate support?</h4>
            <p>You're not alone. Help is available 24/7</p>
          </div>
          <button style={styles.emergencyBtn} onClick={() => navigate('/emergency')}>
            Get Help Now →
          </button>
        </div>
      </div>

      {/* Add Academic Item Modal */}
      {showAcademicForm && (
        <div style={styles.modal}>
          <div style={styles.modalContent}>
            <h3>Add Academic Task</h3>
            <input
              type="text"
              placeholder="Task title (e.g., Math Exam)"
              value={newAcademicItem.title}
              onChange={(e) => setNewAcademicItem({...newAcademicItem, title: e.target.value})}
              style={styles.modalInput}
            />
            <select
              value={newAcademicItem.type}
              onChange={(e) => setNewAcademicItem({...newAcademicItem, type: e.target.value})}
              style={styles.modalSelect}
            >
              <option value="exam">📝 Exam</option>
              <option value="assignment">📄 Assignment</option>
              <option value="club">👥 Club Meeting</option>
              <option value="work">💼 Work Shift</option>
            </select>
            <input
              type="date"
              value={newAcademicItem.dueDate}
              onChange={(e) => setNewAcademicItem({...newAcademicItem, dueDate: e.target.value})}
              style={styles.modalInput}
            />
            <select
              value={newAcademicItem.priority}
              onChange={(e) => setNewAcademicItem({...newAcademicItem, priority: e.target.value})}
              style={styles.modalSelect}
            >
              <option value="low">🟢 Low Priority</option>
              <option value="medium">🟡 Medium Priority</option>
              <option value="high">🔴 High Priority</option>
            </select>
            <div style={styles.modalActions}>
              <button onClick={addAcademicItem} style={styles.modalSaveBtn}>Save</button>
              <button onClick={() => setShowAcademicForm(false)} style={styles.modalCancelBtn}>Cancel</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const styles = {
  container: {
    minHeight: '100vh',
    background: '#f5f7fa',
  },
  content: {
    maxWidth: '1200px',
    margin: '0 auto',
    padding: '20px',
    paddingTop: '80px',
  },
  
  // Welcome Card
  welcomeCard: {
